-- Backfill main_location_geom for users who have main_location_text but no coordinates.
-- Uses sgg-level (시/구) centroids. Not exact per-dong but close enough for distance display.
-- Only updates users where main_location_geom IS NULL (idempotent).

UPDATE users SET main_location_geom = ST_SetSRID(ST_MakePoint(128.877539, 37.74959), 4326) WHERE main_location_text LIKE '강원 강릉%' AND main_location_geom IS NULL;
